183→function FieldError({
184→  className,
185→  children,
186→  errors,
187→  ...props
188→}: React.ComponentProps<'div'> & {
189→  errors?: Array<{ message?: string } | undefined>;
190→}) {
191→  const content = useMemo(() => {
192→    if (children) {
193→      return children;
194→    }
195→
196→    if (!errors?.length) {
197→      return null;
198→    }
199→
200→    if (errors?.length == 1) {
201→      return errors[0]?.message;
202→    }
203→
204→    return (
