import { cn } from 'lib/utils';

interface InputProps extends React.InputHTMLAttributes<HTMLInputElement> {
  label?: string;
  error?: boolean;
  disabled?: boolean;
  iconBefore?: React.ReactNode;
  iconAfter?: React.ReactNode;
  variant: 'small' | 'medium' | 'large';
  errorMessage?: string;
}

export const Input: React.FC<InputProps> = ({
  id,
  name,
  disabled,
  label,
  type = 'text',
  error,
  variant = 'small',
  iconBefore,
  iconAfter,
  errorMessage,
  defaultValue,
  placeholder,
  onChange,
}) => {
  // Tailwind classes for input, label, and size variants
  // Includes responsive sizing, error states, and disabled styling
  // Returns a wrapper div with label, input field with icons, and error message
